# Generated by /validate-function raincloud depth=exhaustive (2026-11-19).
# Live tests lock in verified mathematical/statistical behaviour.
# Open defects carry the CORRECT expectation guarded by skip("VAL-raincloud-NN ...").

library(testthat)

# ---- Local helpers -----------------------------------------------------------
val_strip_html <- function(html) {
  if (is.null(html) || !nzchar(html)) return("")
  t <- gsub("<[a-zA-Z/!][^>]*>", " ", html)
  t <- gsub("&lt;", "<", t, fixed = TRUE)
  t <- gsub("&gt;", ">", t, fixed = TRUE)
  t <- gsub("&amp;", "&", t, fixed = TRUE)
  trimws(gsub("\\s+", " ", t))
}

val_parse_table <- function(html) {
  tr_m <- gregexpr("<tr[^>]*>.*?</tr>", html, perl = TRUE)
  trs <- regmatches(html, tr_m)[[1]]
  rows <- lapply(trs, function(tr) {
    td_m <- gregexpr("<t[dh][^>]*>.*?</t[dh]>", tr, perl = TRUE)
    vapply(regmatches(tr, td_m)[[1]], val_strip_html, character(1))
  })
  mat <- do.call(rbind, rows)
  if (grepl("<th", trs[1], fixed = TRUE) && nrow(mat) > 1) {
    df <- as.data.frame(mat[-1, , drop = FALSE], stringsAsFactors = FALSE)
    names(df) <- mat[1, ]
    df
  } else {
    as.data.frame(mat, stringsAsFactors = FALSE)
  }
}

val_comp_kv <- function(html) {
  tbl <- regmatches(html, regexpr("<table[^>]*>.*?</table>", html, perl = TRUE))
  df <- val_parse_table(tbl)
  setNames(trimws(df[[2]]), sub(":$", "", trimws(df[[1]])))
}

val_pairwise_tbl <- function(html) {
  tbls <- regmatches(html, gregexpr("<table[^>]*>.*?</table>", html, perl = TRUE))[[1]]
  if (length(tbls) < 2) return(data.frame())
  val_parse_table(tbls[2])
}

val_outliers_list <- function(html) {
  lis <- regmatches(html, gregexpr("<li>.*?</li>", html, perl = TRUE))[[1]]
  res <- list()
  for (li in lis) {
    parts <- strsplit(val_strip_html(li), ":", fixed = TRUE)[[1]]
    if (length(parts) >= 2) res[[trimws(parts[1])]] <- trimws(paste(parts[-1], collapse = ":"))
  }
  res
}

# ---- LIVE TESTS: Verified PASS claims ----------------------------------------

test_that("C05-C13: Known-answer summary statistics match hand calculations", {
  # Oracle: exact hand arithmetic on A=c(2,4,4,6,9) and B=c(10,12,12,14,16,20) with 1 NA
  d <- data.frame(
    y = c(2, 4, 4, 6, 9, NA, 10, 12, 12, 14, 16, 20),
    g = factor(c(rep("A", 6), rep("B", 6)), levels = c("A", "B"))
  )
  res <- suppressWarnings(ClinicoPath::raincloud(
    data = d, dep_var = "y", group_var = "g", show_statistics = TRUE
  ))
  tb <- val_parse_table(res$statistics$content)
  rowA <- tb[tb$Group == "A", , drop = FALSE]
  rowB <- tb[tb$Group == "B", , drop = FALSE]

  expect_equal(as.numeric(rowA$N), 5)
  expect_equal(as.numeric(rowA$Mean), 5, tolerance = 1e-8)
  expect_equal(as.numeric(rowA$Median), 4, tolerance = 1e-8)
  expect_equal(as.numeric(rowA$SD), round(sqrt(7), 3), tolerance = 1e-8)
  expect_equal(as.numeric(rowA$MAD), round(2 * 1.4826, 3), tolerance = 1e-8)
  expect_equal(as.numeric(rowA$IQR), 2, tolerance = 1e-8)
  expect_equal(rowA$Range, "2 - 9")
  expect_equal(as.numeric(rowA$Skewness), round(7.2 / 5.6^1.5, 3), tolerance = 1e-8)
  expect_equal(as.numeric(rowA$Kurtosis), round(68 / 5.6^2, 3), tolerance = 1e-8)

  expect_equal(as.numeric(rowB$N), 6)
  expect_equal(as.numeric(rowB$Mean), 14, tolerance = 1e-8)
  expect_equal(as.numeric(rowB$Median), 13, tolerance = 1e-8)
  expect_equal(as.numeric(rowB$SD), round(sqrt(12.8), 3), tolerance = 1e-8)
  expect_equal(as.numeric(rowB$IQR), 3.5, tolerance = 1e-8)
  expect_equal(rowB$Range, "10 - 20")
})

test_that("C14-C16: Outlier detection exact boundaries for IQR, Z-score, and Modified Z-score", {
  # Oracle: exact closed-form Tukey 1.5*IQR, sample-SD Z-score (>3), Iglewicz-Hoaglin ModZ (>3.5)
  d_iqr_eq <- data.frame(y = c(0, 10, 10, 15, 15, 15, 20, 20, 35),    g = factor(rep("G", 9)))
  d_iqr_gt <- data.frame(y = c(0, 10, 10, 15, 15, 15, 20, 20, 35.01), g = factor(rep("G", 9)))
  r_eq <- ClinicoPath::raincloud(data = d_iqr_eq, dep_var = "y", group_var = "g", show_outliers = TRUE, outlier_method = "iqr")
  r_gt <- ClinicoPath::raincloud(data = d_iqr_gt, dep_var = "y", group_var = "g", show_outliers = TRUE, outlier_method = "iqr")
  expect_equal(val_outliers_list(r_eq$outliers$content)[["G"]], "0 outliers detected")
  expect_equal(val_outliers_list(r_gt$outliers$content)[["G"]], "1 outliers detected")

  d_z1 <- data.frame(y = c(rep(0, 10), 100), g = factor(rep("G", 11)))
  d_z0 <- data.frame(y = c(rep(0, 9),  100), g = factor(rep("G", 10)))
  r_z1 <- ClinicoPath::raincloud(data = d_z1, dep_var = "y", group_var = "g", show_outliers = TRUE, outlier_method = "zscore")
  r_z0 <- ClinicoPath::raincloud(data = d_z0, dep_var = "y", group_var = "g", show_outliers = TRUE, outlier_method = "zscore")
  expect_equal(val_outliers_list(r_z1$outliers$content)[["G"]], "1 outliers detected")
  expect_equal(val_outliers_list(r_z0$outliers$content)[["G"]], "0 outliers detected")

  d_mz1 <- data.frame(y = c(1, 2, 3, 4, 5, 6, 7, 8, 25), g = factor(rep("G", 9)))
  d_mz0 <- data.frame(y = c(1, 2, 3, 4, 5, 6, 7, 8, 15), g = factor(rep("G", 9)))
  r_mz1 <- ClinicoPath::raincloud(data = d_mz1, dep_var = "y", group_var = "g", show_outliers = TRUE, outlier_method = "modified_zscore")
  r_mz0 <- ClinicoPath::raincloud(data = d_mz0, dep_var = "y", group_var = "g", show_outliers = TRUE, outlier_method = "modified_zscore")
  expect_equal(val_outliers_list(r_mz1$outliers$content)[["G"]], "1 outliers detected")
  expect_equal(val_outliers_list(r_mz0$outliers$content)[["G"]], "0 outliers detected")
})

test_that("C19-C21: Welch t-test, unpooled Cohen's d, and Wilcoxon match closed-form oracles", {
  # Oracle: Welch-Satterthwaite t & df, average-variance Cohen's d, Mann-Whitney U
  x <- c(2, 4, 4, 6, 9); y <- c(10, 12, 12, 14, 16, 20)
  d <- data.frame(y = c(x, y), g = factor(c(rep("A", 5), rep("B", 6)), levels = c("A", "B")))

  v1 <- var(x); v2 <- var(y); se2 <- v1 / 5 + v2 / 6
  t_exp <- (mean(x) - mean(y)) / sqrt(se2)
  df_exp <- se2^2 / ((v1 / 5)^2 / 4 + (v2 / 6)^2 / 5)
  p_exp <- 2 * stats::pt(-abs(t_exp), df = df_exp)
  d_exp <- (mean(x) - mean(y)) / sqrt((v1 + v2) / 2)

  r_t <- ClinicoPath::raincloud(data = d, dep_var = "y", group_var = "g",
                                comparison_test = TRUE, comparison_method = "ttest", effect_size = TRUE)
  kv <- val_comp_kv(r_t$comparison$content)
  expect_equal(kv[["Test Method"]], "Welch's t-test")
  expect_equal(kv[["Test Statistic"]], paste0("t = ", round(t_exp, 4), ", df = ", round(df_exp, 1)))
  expect_equal(kv[["P-value"]], formatC(p_exp, format = "f", digits = 3))
  expect_equal(kv[["Cohen's d (unpooled SD, matching Welch's t) [A - B]"]], sprintf("%.3f", d_exp))

  r_w <- suppressWarnings(ClinicoPath::raincloud(data = d, dep_var = "y", group_var = "g",
                                                 comparison_test = TRUE, comparison_method = "wilcoxon"))
  expect_match(val_comp_kv(r_w$comparison$content)[["Test Statistic"]], "^W = 0 \\(")
})

test_that("C22-C24, C26: ANOVA, Welch's ANOVA, Kruskal-Wallis, and pairwise adjustments match independent oracles", {
  # Oracle: closed-form one-way ANOVA, Welch (1951) ANOVA, tie-corrected Kruskal-Wallis, Bonferroni/Holm
  d_aov <- datasets::PlantGrowth
  r_pg <- ClinicoPath::raincloud(data = d_aov, dep_var = "weight", group_var = "group",
                                 comparison_test = TRUE, comparison_method = "auto")
  kv_pg <- val_comp_kv(r_pg$comparison$content)
  expect_equal(kv_pg[["Test Method"]], "one-way ANOVA")
  expect_equal(kv_pg[["Test Statistic"]], "F(2,27) = 4.8461")
  expect_equal(kv_pg[["P-value"]], "0.016")

  set.seed(25)
  d_w <- data.frame(
    y = c(stats::rnorm(6, 50, 8), stats::rnorm(6, 50, 8), stats::rnorm(60, 50, 1)),
    g = factor(rep(c("A", "B", "C"), times = c(6, 6, 60)))
  )
  r_w <- ClinicoPath::raincloud(data = d_w, dep_var = "y", group_var = "g",
                                comparison_test = TRUE, comparison_method = "auto", adjust_method = "holm")
  kv_w <- val_comp_kv(r_w$comparison$content)
  expect_equal(kv_w[["Test Method"]], "Welch's ANOVA")
  expect_equal(kv_w[["Test Statistic"]], "F(2,6.7) = 2.5101")
  expect_equal(kv_w[["P-value"]], "0.154")

  r_bio <- ClinicoPath::raincloud(data = ClinicoPath::raincloud_biomarker,
                                  dep_var = "ki67_index", group_var = "cancer_type",
                                  comparison_test = TRUE, comparison_method = "kruskal")
  kv_bio <- val_comp_kv(r_bio$comparison$content)
  expect_equal(kv_bio[["Test Statistic"]], "\u03c7\u00b2 = 1.6112, df = 3")
  expect_equal(kv_bio[["P-value"]], "0.657")
})

test_that("C06, C19, C20, C24: Metamorphic invariants (permutation, level swap, affine/monotone transform)", {
  # Oracle: algebraic invariance properties of location/scale, t, d, W, Kruskal-Wallis
  d <- data.frame(
    y = c(2, 4, 4, 6, 9, 10, 12, 12, 14, 16, 20),
    g = factor(c(rep("A", 5), rep("B", 6)), levels = c("A", "B"))
  )
  r0 <- ClinicoPath::raincloud(data = d, dep_var = "y", group_var = "g",
                               show_statistics = TRUE, comparison_test = TRUE,
                               comparison_method = "ttest", effect_size = TRUE)

  set.seed(101)
  r_perm <- ClinicoPath::raincloud(data = d[sample(nrow(d)), ], dep_var = "y", group_var = "g",
                                   show_statistics = TRUE, comparison_test = TRUE,
                                   comparison_method = "ttest", effect_size = TRUE)
  expect_identical(r_perm$statistics$content, r0$statistics$content)
  expect_identical(r_perm$comparison$content, r0$comparison$content)

  d_swap <- d; d_swap$g <- factor(d_swap$g, levels = c("B", "A"))
  r_swap <- ClinicoPath::raincloud(data = d_swap, dep_var = "y", group_var = "g",
                                   comparison_test = TRUE, comparison_method = "ttest", effect_size = TRUE)
  kv0 <- val_comp_kv(r0$comparison$content)
  kvs <- val_comp_kv(r_swap$comparison$content)
  expect_equal(kvs[["P-value"]], kv0[["P-value"]])
  expect_equal(as.numeric(kvs[["Cohen's d (unpooled SD, matching Welch's t) [B - A]"]]),
               -as.numeric(kv0[["Cohen's d (unpooled SD, matching Welch's t) [A - B]"]]))

  d_aff <- d; d_aff$y <- 10 * d_aff$y + 100
  r_aff <- ClinicoPath::raincloud(data = d_aff, dep_var = "y", group_var = "g",
                                  comparison_test = TRUE, comparison_method = "ttest", effect_size = TRUE)
  expect_equal(val_comp_kv(r_aff$comparison$content)[["Test Statistic"]], kv0[["Test Statistic"]])
})

