# ---- REGRESSION TESTS FOR REPAIRED DEFECTS (VAL-raincloud-01 .. 09) ----------

test_that("C30: Plot highlighted outliers match Outlier Analysis under zscore and log_transform", {
  # VAL-raincloud-01: geom_boxplot suppresses built-in IQR outliers; dedicated geom_point layer matches outlier_method
  capture_plot <- function(d, ...) {
    opts <- do.call(ClinicoPath:::raincloudOptions$new, c(list(dep_var = "y", group_var = "g"), list(...)))
    a <- ClinicoPath:::raincloudClass$new(options = opts, data = d)
    a$init(); a$.__enclos_env__$private$.run()
    captured <- NULL
    env <- new.env(parent = environment(a$.__enclos_env__$private$.plot))
    env$print <- function(x, ...) { captured <<- x; invisible(x) }
    fn <- a$.__enclos_env__$private$.plot; environment(fn) <- env
    fn(a$results$plot, ggplot2::theme_minimal(), list())
    captured
  }
  count_drawn_outliers <- function(p) {
    # geom_boxplot must have outlier.shape = NA; outlier points come from GeomPoint layer(s)
    pt_layers <- which(vapply(p$layers, function(l) inherits(l$geom, "GeomPoint"), logical(1)))
    if (length(pt_layers) == 0) return(0L)
    gb <- ggplot2::ggplot_build(p)
    sum(vapply(pt_layers, function(i) nrow(gb$data[[i]]), integer(1)))
  }

  # Z-score flags 0 outliers on d_z -> plot must draw 0 outlier points
  d_z <- data.frame(y = c(0, 10, 10, 15, 15, 15, 20, 20, 36), g = factor(rep("G", 9)))
  p_z <- capture_plot(d_z, show_outliers = TRUE, outlier_method = "zscore")
  expect_equal(count_drawn_outliers(p_z), 0L)

  # Raw IQR flags 1 outlier (24) on d_log even with log_transform = TRUE -> plot must draw 1 outlier point
  d_log <- data.frame(y = c(1, 2, 3, 4, 5, 6, 7, 8, 24), g = factor(rep("G", 9)))
  p_log <- capture_plot(d_log, show_outliers = TRUE, outlier_method = "iqr", log_transform = TRUE)
  expect_equal(count_drawn_outliers(p_log), 1L)
})

test_that("C25: Auto 3-group unequal-variance/n Type I error stays within nominal 5% MC band", {
  # VAL-raincloud-02: Bonferroni/heteroscedasticity-calibrated Shapiro-Wilk keeps auto Type I error nominal
  set.seed(20260202)
  R <- 500L
  sig <- sum(vapply(seq_len(R), function(i) {
    d <- data.frame(y = c(stats::rnorm(6, 50, 8), stats::rnorm(6, 50, 8), stats::rnorm(60, 50, 1)),
                    g = factor(rep(c("A", "B", "C"), times = c(6, 6, 60))))
    res <- suppressWarnings(ClinicoPath::raincloud(data = d, dep_var = "y", group_var = "g",
                                                   comparison_test = TRUE, comparison_method = "auto"))
    val_comp_kv(res$comparison$content)[["Result"]] != "not significant at the 0.05 level"
  }, logical(1)))
  expect_lt(sig / R, 0.05 + 3 * sqrt(0.05 * 0.95 / R))
})

